var n=`0509-malawach`;var o=`world-0509`;var a=`IL`;var i=`western-asia`;var r=8;var s=87;var l={en:`Malawach`,ua:`Малауах`};var u={en:`A traditional dish from Israel, centered on all-purpose flour. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ізраїль. Основні складники: пшеничне борошно універсальне. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 15 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 15 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:15,i:[[`all-purpose-flour`,430,`g`],[`water`,215,`ml`],[`table-salt`,7,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:14,i:[[`unsalted-butter`,180,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 40 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 40 хвилин.`,t:[`rapid-chilling`],m:40,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[]}];var h={slug:n,id:o,country:`IL`,region:i,servings:8,minutes:87,title:l,text:u,steps:d};export{a as country,h as default,o as id,s as minutes,i as region,r as servings,n as slug,d as steps,u as text,l as title};